    "hero_sub": "విత్తడం నుండి అమ్మకం వరకు, మొత్తం పంట చక్రంలో KrishiSathi మీకు తోడుగా ఉంటుంది. ఫోటో ద్వారా పంట ఆరోగ్యాన్ని చెక్ చేయండి, లైవ్ మండి ధరలను చూడండి, ముందుగానే వాతావరణ హెచ్చరికలను పొందండి మరియు అమ్మాల్సిన సరైన సమయాన్ని తెలుసుకోండి.",
