    "hero_welcome_guest": "ಸ್ವಾಗತ, ಅತಿಥಿ — ಮುಕ್ತವಾಗಿ ಅನ್ವೇಷಿಸಿ, ಖಾತೆ ಅಗತ್ಯವಿಲ್ಲ.",
