    "hero_sub": "ಬಿತ್ತನೆಯಿಂದ ಮಾರಾಟದವರೆಗೆ ಇಡೀ ಬೆಳೆ ಚಕ್ರದಲ್ಲಿ ಕೃಷಿ ಸಖಿ ನಿಮ್ಮೊಂದಿಗೆ ಹೆಜ್ಜೆ ಹಾಕುತ್ತದೆ. ಫೋಟೋದಿಂದ ಬೆಳೆಯ ಆರೋಗ್ಯವನ್ನು ಪರಿಶೀಲಿಸಿ, ಲೈವ್ ಮಂಡಿ ಬೆಲೆಗಳನ್ನು ನೋಡಿ, ಮುಂಚಿತವಾಗಿ ಹವಾಮಾನ ಎಚ್ಚರಿಕೆಗಳನ್ನು ಪಡೆಯಿರಿ ಮತ್ತು ಮಾರಾಟ ಮಾಡಲು ಸರಿಯಾದ ಸಮಯವನ್ನು ತಿಳಿದುಕೊಳ್ಳಿ.",
    "doctor_desc": "ಬಾಧಿತ ಎಲೆ, ಕಾಂಡ ಅಥವಾ ಹಣ್ಣಿನ ಸ್ಪಷ್ಟ ಫೋಟೋವನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ. AI ರೋಗ ಅಥವಾ ಕೀಟವನ್ನು ಗುರುತಿಸುತ್ತದೆ ಮತ್ತು ಚಿಕಿತ್ಸೆಯನ್ನು ಸೂಚಿಸುತ್ತದೆ.",
    "doctor_choose": "ಫೋಟೋ ಆಯ್ಕೆ ಮಾಡಲು ಟ್ಯಾಪ್ ಮಾಡಿ",
