export const LANG_NAMES_EN = {
  "en": "English",
  "hi": "Hindi",
  "bn": "Bengali",
  "ta": "Tamil",
  "te": "Telugu",
  "mr": "Marathi",
  "gu": "Gujarati",
  "kn": "Kannada",
  "ml": "Malayalam",
  "or": "Odia",
  "pa": "Punjabi",
  "ur": "Urdu",
  "as": "Assamese",
  "ne": "Nepali",
  "sd": "Sindhi",
  "ks": "Kashmiri",
  "kok": "Konkani",
  "mai": "Maithili",
  "doi": "Dogri",
  "brx": "Bodo",
  "sa": "Sanskrit",
  "sat": "Santali",
  "mni": "Manipuri (Meiteilon)"
}; // lang code -> English name (for AI prompts)

const STORAGE_KEY = 'ks_lang';
let current = (() => {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved && STRINGS[saved]) return saved;
  } catch {}
  try {
    // fall back to the browser's own language if we support it
    const nav = (navigator.language || 'en').slice(0, 2);
    return STRINGS[nav] ? nav : 'en';
  } catch {}
  return 'en';
})();

/** Translate a key. Falls back to English, then to the key itself. */
export function t(key) {
  return (STRINGS[current] && STRINGS[current][key]) || STRINGS.en[key] || key;
}

/** The active language code, e.g. 'hi'. */
export function getLang() {
  return current;
}

/** The English name of the active language, e.g. 'Hindi' (for AI prompts). */
export function getLangName() {
  return LANG_NAMES_EN[current] || 'English';
}

/** The active BCP-47 tag for speech (TTS + voice input), e.g. 'hi-IN'. */
export function getSpeechLang() {
  return current === 'en' ? 'en-IN' : current + '-IN';
}

/**
 * Switch the interface language. The caller re-renders the current page
 * afterwards so every visible string updates.
 */
export function setLang(code) {
  if (!STRINGS[code]) return;
  current = code;
  try {
    localStorage.setItem(STORAGE_KEY, code);
  } catch {}
  try {
    document.documentElement.lang = code;
  } catch {}
}
